--Screen table create table screens (id integer primary key,name text,p_id integer default 0);
delete from screens; insert or ignore into screens(id,name,p_id) values(1,'عمليات مخزنية',0); insert or ignore into screens(id,name,p_id) values(2,'قيود وحسابات',0); insert or ignore into screens(id,name,p_id) values(3,'أصناف',0); insert or ignore into screens(id,name,p_id) values(4,'العملات ',0); insert or ignore into screens(id,name,p_id) values(5,'التقارير',0); insert or ignore into screens(id,name,p_id) values(6,'تحويل مخزني',1); insert or ignore into screens(id,name,p_id) values(7,'تسوية مخزنية',1); insert or ignore into screens(id,name,p_id) values(8,'إضافة مخزن',1); insert or ignore into screens(id,name,p_id) values(9,'قيد يومي',2); insert or ignore into screens(id,name,p_id) values(10,'قيد إفتتاحي',2); insert or ignore into screens(id,name,p_id) values(11,'إضافة حساب',2); insert or ignore into screens(id,name,p_id) values(12,'حركة الصندوق',2); insert or ignore into screens(id,name,p_id) values(13,'دليل الحسابات',2); insert or ignore into screens(id,name,p_id) values(14,'إقفال سنوي',2); insert or ignore into screens(id,name,p_id) values(15,'الأصناف',3); insert or ignore into screens(id,name,p_id) values(16,'أسعار البيع',3); insert or ignore into screens(id,name,p_id) values(17,'المخزون',3); insert or ignore into screens(id,name,p_id) values(18,'أرباح الأصناف',3); insert or ignore into screens(id,name,p_id) values(19,'إضافة عملة',4); insert or ignore into screens(id,name,p_id) values(20,'سعر العملات',4); insert or ignore into screens(id,name,p_id) values(21,'حركة الأصناف',5); insert or ignore into screens(id,name,p_id) values(22,'المخزون',5); insert or ignore into screens(id,name,p_id) values(23,'ميزان المراجعة',5); insert or ignore into screens(id,name,p_id) values(24,'قائمة الدخل',5); insert or ignore into screens(id,name,p_id) values(25,'المركز المالي',5); insert or ignore into screens(id,name,p_id) values(26,'تقارير أخرى',5);
CREATE TABLE IF NOT EXISTS notifications ( `id` INTEGER PRIMARY KEY, `name` TEXT , date_ text default (strftime('%Y-%m-%d','now')), status integer default 0, param1 text, param2 text )
create table closing_year (id integer primary key autoincrement,date_ text, cnt real default 0, now_ text default (strftime('%Y-%m-%d','now')));
